-- ===== Kunxo'ja =====
UPDATE fact_cards SET topic_ru = 'Моё рождение', question_ru = 'В каком году родился Кунходжа и каково его полное имя?', fact_ru = 'Я родился в 1799 году. Моё полное имя — Кунходжа, сын Ибрахима, то есть моего отца звали Ибрахим. В каком селении я появился на свет, в источнике не записано, потому это точно не известно.' WHERE id = 2203;
UPDATE fact_cards SET topic_ru = 'Я каракалпакский поэт', question_ru = 'Поэтом какого народа был Кунходжа?', fact_ru = 'Я каракалпакский поэт. Свои стихи я писал на языке моего народа и воспевал в них жизнь простых людей.' WHERE id = 2204;
UPDATE fact_cards SET topic_ru = 'Мои стихи о трудовом народе', question_ru = 'Что отразил Кунходжа в стихах «Жнецы», «Белый камыш» и «Чабаны»?', fact_ru = 'Я написал стихи «Жнецы», «Белый камыш» и «Чабаны». В них я отразил жизнь каракалпаков, тяготы их быта и надежды на приход лучших дней.' WHERE id = 2205;
UPDATE fact_cards SET topic_ru = 'Мои стихи против несправедливости', question_ru = 'Что разоблачил Кунходжа в стихах «Байский сын», «С народом», «Дитя моё»?', fact_ru = 'В таких стихах, как «Байский сын», «С народом», «Дитя моё», я раскрыл общественные противоречия и несправедливость и разоблачил проделки людей бессовестных и немилосердных.' WHERE id = 2206;
UPDATE fact_cards SET topic_ru = 'Мои лучшие произведения', question_ru = 'Какие произведения Кунходжи считаются лучшими образцами каракалпакской классической поэзии?', fact_ru = 'Я написал также произведения «Не забуду», «Верблюдом оказался ты» и «Где же солнце». Эти стихи принадлежат моему перу.' WHERE id = 2207;
UPDATE fact_cards SET topic_ru = 'Мои беседы с Бердахом', question_ru = 'Почему Бердах читал свои стихи Кунходже?', fact_ru = 'Поэт Бердах читал мне свои стихи, а я указывал ему на недостатки и помогал их исправить.' WHERE id = 2208;
UPDATE fact_cards SET topic_ru = 'Конец моей жизни', question_ru = 'В каком году умер Кунходжа?', fact_ru = 'Я скончался в 1880 году. Где я умер и где моя могила, в источнике не записано, потому это точно не известно.' WHERE id = 2209;
UPDATE fact_cards SET topic_ru = 'Мои стихи стали книгой', question_ru = 'В каких книгах напечатаны стихи Кунходжи?', fact_ru = 'Я скончался в 1880 году. После меня мои стихи вышли книгами: сборник «Стихи» издан на узбекском языке в переводе Захиджана Абидова в 1973 году, а на каракалпакском вышли мои книги «Косыклар» (1960) и «Эль менен» (1975, 1984, 1989).' WHERE id = 2210;

-- ===== Fayzulla Xo'jayev =====
UPDATE fact_cards SET topic_ru = 'Моё рождение', question_ru = 'Когда и где родился Файзулла Ходжаев?', fact_ru = 'Я родился 1 июля 1896 года в городе Бухаре, в семье крупного купца. От отца мне досталось большое богатство.' WHERE id = 2178;
UPDATE fact_cards SET topic_ru = 'Моё образование', question_ru = 'Где учился Файзулла Ходжаев?', fact_ru = 'В юности я окончил старую школу и учился в бухарском медресе. А в 1907–1912 годах я получал образование в Москве.' WHERE id = 2179;
UPDATE fact_cards SET topic_ru = 'Моё участие в джадидизме', question_ru = 'Как участвовал Файзулла Ходжаев в движении джадидов?', fact_ru = 'С 1913 года я был деятельным в рядах джадидов: распространял просвещение в народе и тратил доставшееся от отца богатство на открытие школ нового метода.' WHERE id = 2180;
UPDATE fact_cards SET topic_ru = 'Младобухарцы', question_ru = 'Какую роль играл Файзулла Ходжаев в движении младобухарцев?', fact_ru = 'Я действовал в партии младобухарцев. С 1917 года вместе с Фитратом я возглавлял левое крыло партии.' WHERE id = 2181;
UPDATE fact_cards SET topic_ru = 'Глава бухарского правительства', question_ru = 'В какой должности работал Файзулла Ходжаев в Бухарской Народной Советской Республике?', fact_ru = 'После свержения бухарского эмира я был избран главой правительства Бухарской Народной Советской Республики. В 1922 году я ездил в Германию, чтобы заключить договоры с иностранными торговыми компаниями.' WHERE id = 2182;
UPDATE fact_cards SET topic_ru = 'Правительство Узбекистана', question_ru = 'В какой должности работал Файзулла Ходжаев в Узбекистане?', fact_ru = 'В 1925 году я был избран председателем Совета народных назиров (Совета народных комиссаров) Узбекистана и руководил правительством до 1937 года. Я старался наладить связи с Ираном, Турцией, Афганистаном, Китаем, Азербайджаном, Германией и Японией.' WHERE id = 2183;
UPDATE fact_cards SET topic_ru = 'Мои труды', question_ru = 'Какие труды написал Файзулла Ходжаев?', fact_ru = 'Я написал книгу «Материалы к истории бухарской революции» (1926). Моему перу принадлежат и такие статьи, как «Экономическое положение в БНСР» (1924), «Джадиды» (1926) и «Басмачество» (1930).' WHERE id = 2184;
UPDATE fact_cards SET topic_ru = 'Конец моей жизни', question_ru = 'Чем завершилась жизнь Файзуллы Ходжаева?', fact_ru = '9 июля 1937 года я был взят под стражу в Москве и осуждён по беспочвенным обвинениям. Я погиб в 1938 году.' WHERE id = 2185;

-- ===== Abror Hidoyatov =====
UPDATE fact_cards SET topic_ru = 'Моё рождение', question_ru = 'Когда родился Аброр Хидоятов?', fact_ru = 'Я родился в 1900 году. О том, в каком городе я родился, точных сведений в источнике нет, но вся моя жизнь была связана с узбекским театром.' WHERE id = 2100;
UPDATE fact_cards SET topic_ru = 'Мой приход на сцену', question_ru = 'Когда и где Аброр Хидоятов начал свою театральную работу?', fact_ru = 'Свою актёрскую работу я начал в 1918 году. В тот год, когда Маннон Уйгур вновь собрал труппу «Турон», в её ряды вошли мы — я, Фатхулла Умаров, Масума Кариева и Музаффар Мухамедов. В 1921 году нашей труппе было дано имя «Узбекский государственный образцовый театр».' WHERE id = 2101;
UPDATE fact_cards SET topic_ru = 'Мои первые главные роли', question_ru = 'В каких произведениях играл главные роли Аброр Хидоятов в молодости?', fact_ru = 'В молодости я играл главные роли в музыкальных драмах: в 1920 году — роль Немата в произведении Гулама Зафари «Халима», в 1923 году — роль Фархада в произведении Хуршида «Фархад и Ширин». В 1924 году в спектакле «Лейли и Меджнун» я тоже играл главную роль вместе с Масумой Кариевой.' WHERE id = 2102;
UPDATE fact_cards SET topic_ru = 'Мои шекспировские роли', question_ru = 'В каких произведениях Шекспира играл Аброр Хидоятов?', fact_ru = 'Главную роль в трагедии Шекспира «Отелло» я играл несколько лет — академик Камиль Яшен назвал это «бесподобным мастерством». Наш театр поставил и «Гамлета», и чужеземные гости изумлялись нашему исполнению Шекспира.' WHERE id = 2103;
UPDATE fact_cards SET topic_ru = 'Моя роль Гафура', question_ru = 'Какую роль играл Аброр Хидоятов в спектакле «Бай и батрак»?', fact_ru = 'Когда в 1939 году драма Хамзы «Бай и батрак» была поставлена в академическом драматическом театре, роль Гафура первым сыграл я. Моими партнёрами были Сора Эшонтураева в роли Джамили и Обид Джалилов в роли Салихбая. Этот спектакль стал самым любимым зрелищем для зрителей.' WHERE id = 2104;
UPDATE fact_cards SET topic_ru = 'Навои и Муканна', question_ru = 'Когда Аброр Хидоятов сыграл роли Алишера Навои и Муканны?', fact_ru = 'В 1944 году я сыграл роль Муканны в драме Хамида Алимджана «Муканна», а в спектакле «Алишер Навои», премьера которого прошла 1 апреля 1945 года, — роль Навои. О роли Навои я написал так: «Это была очень трудная творческая работа в моей жизни... Ибо образ Навои — самый любимый герой нашего народа».' WHERE id = 2105;
UPDATE fact_cards SET topic_ru = 'Мои наставления ученикам', question_ru = 'Какие наставления давал Аброр Хидоятов своим ученикам?', fact_ru = 'В пьесе «Джалалиддин Мангуберди» я исполнял роль Тимура Малика, а потом собственноручно передал перепечатанный на машинке текст этой роли молодому актёру Зикиру Мухаммаджанову и репетировал с ним в театре. Своим ученикам я наставлял: «На сцене ничего не делай впустую... если твои слова не идут от сердца, ты не убедишь зрителя».' WHERE id = 2106;
UPDATE fact_cards SET topic_ru = 'Конец моей жизни', question_ru = 'Когда умер Аброр Хидоятов?', fact_ru = 'Я скончался в 1958 году. Мой сценический путь, начавшийся в 1918 году в труппе «Турон», длился сорок лет, и я посвятил свою жизнь узбекскому театру.' WHERE id = 2107;

-- ===== Chingiz Ahmarov =====
UPDATE fact_cards SET topic_ru = 'Моё рождение', question_ru = 'Когда и где родился Чингиз Ахмаров?', fact_ru = 'Я родился 18 августа 1912 года в городе Троицке — этот город расположен в нынешней Челябинской области. Моё полное имя — Чингиз Габдурахманович Ахмаров.' WHERE id = 2146;
UPDATE fact_cards SET topic_ru = 'Моё образование', question_ru = 'Где учился Чингиз Ахмаров?', fact_ru = 'В 1927–1930 годах я учился в Пермском художественном техникуме, а затем, в 1935–1942 годах, — в Московском художественном институте имени В. Сурикова.' WHERE id = 2147;
UPDATE fact_cards SET topic_ru = 'Мои росписи в театре Навои', question_ru = 'Какие росписи выполнил Чингиз Ахмаров в театре Навои?', fact_ru = 'В 1944–1947 годах я выполнил в фойе театра Навои монументальные росписи по мотивам «Хамсы» Навои. В фойе театра есть и моя роспись «Фархад и Ширин». С этой поры восточная тема заняла в моём творчестве широкое место.' WHERE id = 2148;
UPDATE fact_cards SET topic_ru = 'Моя манера и миниатюра', question_ru = 'В чём особенности манеры Чингиза Ахмарова?', fact_ru = 'В своём творчестве я продолжил традиции восточной миниатюры и создал национальную школу живописи. На моих картинах человеческие фигуры парят в воздухе, линии мои музыкальны, как струна дутара, а краски прозрачны и чисты.' WHERE id = 2149;
UPDATE fact_cards SET topic_ru = 'Моё раннее творчество и книжная графика', question_ru = 'Какие книги оформлял Чингиз Ахмаров?', fact_ru = 'Своё творчество я начал в 30-е годы со станковой живописи и графики: оформил книгу Ш. Сулаймана «Ли Чу» (1934), рисовал для журналов «Муштум» и «Машъала». В годы войны я создал триптих «Меч Узбекистана» (1942). Затем я выполнил книжное оформление для романа Айбека «Навои» (1951) и эпоса «Равшан» (1958).' WHERE id = 2150;
UPDATE fact_cards SET topic_ru = 'Написанные мной портреты', question_ru = 'Чьи портреты написал Чингиз Ахмаров?', fact_ru = 'С 50-х годов я вырос в многогранного художника: я создал портреты М. Тургунбаевой (1952), художника Р. Темурова (1961), поэтессы Зульфии (1965), Халимы Насыровой и «Юный Навои» (1968).' WHERE id = 2151;
UPDATE fact_cards SET topic_ru = 'Мои работы в музеях и метро', question_ru = 'Где ещё есть работы Чингиза Ахмарова?', fact_ru = 'Я выполнил росписи для мемориального музея Улугбека в Самарканде (1964), Музея литературы имени Навои (1968) и Института востоковедения имени Беруни (1968–1969). В 80–90-е годы я создал работы и на стенах станции «Алишер Навои» Ташкентского метрополитена и здания Музея прикладного искусства.' WHERE id = 2152;
UPDATE fact_cards SET topic_ru = 'Мои звания и награды', question_ru = 'Каких званий и наград удостоился Чингиз Ахмаров?', fact_ru = 'В 1964 году мне было присвоено звание народного художника Узбекистана. А в 1968 году я стал лауреатом Государственной премии Узбекистана имени Хамзы.' WHERE id = 2153;
UPDATE fact_cards SET topic_ru = 'Конец моей жизни', question_ru = 'Когда умер Чингиз Ахмаров?', fact_ru = 'Я скончался в 1995 году. Моя жизнь окончилась 13 мая 1995 года в городе Ташкенте. А в последние годы перед этим я создал такие работы, как «Амир Темур и Биби-ханым», «Амир Темур и дервиш», «Амир Темур и Баязид» (1992–1995).' WHERE id = 2154;

-- ===== Habib Abdullayev =====
UPDATE fact_cards SET topic_ru = 'Моё рождение', question_ru = 'Когда и где родился Хабиб Абдуллаев?', fact_ru = 'Я родился 31 августа 1912 года в городе Ош.' WHERE id = 2060;
UPDATE fact_cards SET topic_ru = 'Моя учёба и первая работа', question_ru = 'Какой институт окончил Хабиб Абдуллаев?', fact_ru = 'В 1935 году я окончил горный факультет Среднеазиатского индустриального института. С того же года я работал начальником геологоразведочной партии.' WHERE id = 2061;
UPDATE fact_cards SET topic_ru = 'Как я стал доктором наук', question_ru = 'Когда Хабиб Абдуллаев стал доктором наук?', fact_ru = 'В 1946 году я защитил докторскую диссертацию на тему «Геология шеелитовых скарнов Средней Азии» и стал доктором геолого-минералогических наук. В 1947 году я был избран академиком Академии наук Узбекистана.' WHERE id = 2062;
UPDATE fact_cards SET topic_ru = 'Президент Академии', question_ru = 'В каких должностях работал Хабиб Абдуллаев в Академии наук?', fact_ru = 'С 1947 года я работал вице-президентом Академии наук Узбекистана, а с 1956 года — её президентом. Вместе с тем я руководил и Институтом геологии.' WHERE id = 2063;
UPDATE fact_cards SET topic_ru = 'Мои научные труды', question_ru = 'Сколько научных трудов написал Хабиб Абдуллаев?', fact_ru = 'Я написал более 130 научных трудов, в том числе 7 монографий. Среди них и моя книга «Магматизм Средней Азии и процесс рудообразования» (1960).' WHERE id = 2064;
UPDATE fact_cards SET topic_ru = 'Месторождения и мои открытия', question_ru = 'Какое месторождение изучил Хабиб Абдуллаев и какое открытие он сделал?', fact_ru = 'Я изучил геологическое строение и минеральный состав Лянгарского вольфрамо-молибденового месторождения. Я первым выделил Среднюю Азию как отдельную металлогеническую провинцию.' WHERE id = 2065;
UPDATE fact_cards SET topic_ru = 'Мои ученики', question_ru = 'Сколько учёных выросло под руководством Хабиба Абдуллаева?', fact_ru = 'Под моим руководством 7 человек защитили докторские и 28 человек — кандидатские диссертации. Я первым основал «Геологический журнал Узбекистана» и был его ответственным редактором.' WHERE id = 2066;
UPDATE fact_cards SET topic_ru = 'Конец моей жизни', question_ru = 'Когда умер Хабиб Абдуллаев?', fact_ru = 'Я скончался 20 июня 1962 года в городе Ташкенте. Погребён на Чигатайском кладбище.' WHERE id = 2067;

-- ===== Ubay Orifov =====
UPDATE fact_cards SET topic_ru = 'Моё рождение', question_ru = 'Когда и где родился Убай Арифов?', fact_ru = 'Я родился 15 июня 1905 года в городе Коканде. Позже я вырос в учёного-физика, государственного и общественного деятеля.' WHERE id = 2369;
UPDATE fact_cards SET topic_ru = 'Моя учёба и учёные степени', question_ru = 'Где учился Убай Арифов и каких учёных степеней он достиг?', fact_ru = 'В 1931 году я окончил Педагогическую академию Узбекистана, затем работал в Кокандском хлопковом институте (1932–34) и в УзГУ (1935–41). В 1954 году я стал доктором физико-математических наук, в 1956 году — профессором.' WHERE id = 2370;
UPDATE fact_cards SET topic_ru = 'Институт ядерной физики', question_ru = 'Какими институтами руководил Убай Арифов?', fact_ru = 'Я был директором Института ядерной физики Академии наук Узбекистана (в 1956–62 и 1967–69 годах). Кроме того, я работал в Физико-техническом институте (1945–56, 1963–67) и был директором Института электроники (1966–76).' WHERE id = 2371;
UPDATE fact_cards SET topic_ru = 'Президент Академии наук', question_ru = 'Какие должности занимал Убай Арифов в Академии наук?', fact_ru = 'В 1956 году я стал академиком Академии наук Узбекистана, а в 1962–1966 годах работал президентом Академии наук Узбекистана.' WHERE id = 2372;
UPDATE fact_cards SET topic_ru = 'Мои научные направления', question_ru = 'Каковы были главные научные направления Убая Арифова?', fact_ru = 'Мои главные научные работы посвящены физической электронике, ядерной и радиационной физике, гелиоэнергетике, а также вопросам первичной обработки хлопкового сырья.' WHERE id = 2373;
UPDATE fact_cards SET topic_ru = 'Мои открытия об атомных частицах', question_ru = 'Какие открытия сделал Убай Арифов в физике?', fact_ru = 'Я изучил множество сложных процессов, происходящих при воздействии атомных частиц на твёрдое тело: обнаружил и выделил разные группы вторичных ионов и электронов, установил способы изменения свойств поверхности твёрдых тел. На этой основе были созданы способы обработки материалов для электронной техники, микроэлектроники и машиностроения.' WHERE id = 2374;
UPDATE fact_cards SET topic_ru = 'Солнечная энергия и хлопок', question_ru = 'Что сделал Убай Арифов для солнечной энергетики и хлопководства?', fact_ru = 'Я уделял большое внимание развитию хлопководства и хлопковой промышленности, а также задачам использования солнечной энергии в народном хозяйстве. В итоге исследований под моим руководством были решены задачи полного оголения семенных и технических семян хлопчатника, их сортировки и очистки, выполнены работы по преобразованию солнечной энергии в электрическую и созданию гелиотехнических установок. По моему почину с 1965 года в Ташкенте начал издаваться международный журнал «Гелиотехника».' WHERE id = 2375;
UPDATE fact_cards SET topic_ru = 'Мои труды и награды', question_ru = 'Какие труды написал Убай Арифов и какие награды получил?', fact_ru = 'Я написал книги о взаимодействии атомных частиц с поверхностью металлов и твёрдых тел: «Взаимодействие атомных частиц с поверхностью металла» (Ташкент, 1961) и «Взаимодействие атомных частиц с поверхностью твёрдого тела» (Москва, 1968). В 1959 году мне было присвоено звание заслуженного деятеля науки и техники Узбекистана, а в 1968 году я стал лауреатом Государственной премии Узбекистана имени Беруни.' WHERE id = 2376;
UPDATE fact_cards SET topic_ru = 'Конец моей жизни', question_ru = 'Когда умер Убай Арифов и как увековечена его память?', fact_ru = 'Я скончался 24 декабря 1976 года в городе Ташкенте. После моей смерти моё имя было присвоено Институту электроники Академии наук Узбекистана и одной из улиц Юнусабадского района Ташкента.' WHERE id = 2377;

-- ===== Asqad Muxtor =====
UPDATE fact_cards SET topic_ru = 'Моё рождение', question_ru = 'Когда и где родился Аскад Мухтар?', fact_ru = 'Я родился 23 декабря 1920 года в городе Фергане, в семье железнодорожного рабочего.' WHERE id = 2114;
UPDATE fact_cards SET topic_ru = 'Мой роман «Сёстры»', question_ru = 'Что известно о романе Аскада Мухтара «Сёстры»?', fact_ru = 'В 1955 году я издал свой роман «Сёстры». Это произведение стало одним из важнейших моих романов.' WHERE id = 2115;
UPDATE fact_cards SET topic_ru = 'Мой роман «Чинара»', question_ru = 'Когда был создан роман Аскада Мухтара «Чинара»?', fact_ru = 'Свой роман «Чинара» я издал в 1973 году. Кроме того, я написал романы «Рождение» (1963) и «Время в моей судьбе» (1964).' WHERE id = 2116;
UPDATE fact_cards SET topic_ru = 'Моё поэтическое творчество', question_ru = 'Какие поэтические сборники написал Аскад Мухтар?', fact_ru = 'В поэзии я выпустил такие книги, как «Сталевар» (1947) и «Мои земляки» (1949). «99 миниатюр» и «Колокольчик каравана» — тоже мои поэтические сборники.' WHERE id = 2117;
UPDATE fact_cards SET topic_ru = 'Моя редакторская работа', question_ru = 'Где работал Аскад Мухтар?', fact_ru = 'В 1960–1965 годах я работал главным редактором журнала «Шарк юлдузи». Я был редактором и в журнале «Гулистан», и в еженедельнике «Узбекистон адабиёти ва санъати».' WHERE id = 2118;
UPDATE fact_cards SET topic_ru = 'Мои переводы', question_ru = 'Чьи произведения переводил Аскад Мухтар?', fact_ru = 'Я переводил на узбекский язык произведения Софокла, Пушкина, Лермонтова, Маяковского и Горького. Делал я переводы и из творчества Тагора, Шевченко и Блока.' WHERE id = 2119;
UPDATE fact_cards SET topic_ru = 'Мои награды и звания', question_ru = 'Какие награды и звания получил Аскад Мухтар?', fact_ru = 'В 1972 году я удостоился республиканской Государственной премии имени Хамзы. В 1980 году я получил звание «Народный писатель Узбекистана», а в 1995 году — орден «Дустлик».' WHERE id = 2120;
UPDATE fact_cards SET topic_ru = 'Конец моей жизни', question_ru = 'Когда умер Аскад Мухтар?', fact_ru = 'Я скончался 17 апреля 1997 года в городе Ташкенте.' WHERE id = 2121;

-- ===== Ibroyim Yusupov =====
UPDATE fact_cards SET topic_ru = 'Моё рождение', question_ru = 'Когда и где родился Ибрайим Юсупов?', fact_ru = 'Я появился на свет 5 мая 1929 года в селении Азад Чимбайского района. Моя родина — Каракалпакстан.' WHERE id = 2194;
UPDATE fact_cards SET topic_ru = 'Моя учёба и учительство', question_ru = 'Где учился Ибрайим Юсупов и кого он учил?', fact_ru = 'В 1949 году я окончил Каракалпакский государственный педагогический институт. Затем до 1961 года я преподавал студентам в этом же институте.' WHERE id = 2195;
UPDATE fact_cards SET topic_ru = 'Моё первое стихотворение и проза', question_ru = 'Когда было напечатано первое стихотворение Ибрайима Юсупова?', fact_ru = 'Моё первое стихотворение «Моя Родина» было напечатано в 1946 году. А в 1963 году я написал сборник рассказов «Осень старого тута».' WHERE id = 2196;
UPDATE fact_cards SET topic_ru = 'Мои поэтические сборники', question_ru = 'Какие поэтические сборники написал Ибрайим Юсупов?', fact_ru = 'Я написал такие поэтические сборники, как «Лирика счастья», «Путнику на восход», «Думы», «Семь напевов», «Мечты поля», «Томирис». Мой сборник «Лирика счастья» был издан в 1955 году.' WHERE id = 2197;
UPDATE fact_cards SET topic_ru = 'Мои сценические произведения', question_ru = 'Какие сценические произведения создал Ибрайим Юсупов?', fact_ru = 'Вместе с Аметом Шамуратовым я создал пьесу «Сорок девушек». В 1966 году я написал комедию «Умирбек-балагур», в 1986 году — драму «Сон царя Искандера». А в 1973 году я написал либретто для оперы «Аджинияз».' WHERE id = 2198;
UPDATE fact_cards SET topic_ru = 'Мои переводы из мировой литературы', question_ru = 'Чьи произведения перевёл Ибрайим Юсупов на каракалпакский язык?', fact_ru = 'Я перевёл на каракалпакский язык произведения Пушкина, Лермонтова, Шевченко, Байрона, Гёте, Гейне, Шиллера и Шекспира. Переложил я на родной язык и стихи Алишера Навои и Омара Хайяма.' WHERE id = 2199;
UPDATE fact_cards SET topic_ru = 'Моя руководящая работа', question_ru = 'В каких должностях работал Ибрайим Юсупов?', fact_ru = 'В 1961–1962 годах я был главным редактором журнала «Амударья». В 1965–1980 годах я председательствовал в Союзе писателей Каракалпакстана. А в 1980–1988 годах работал главным редактором газеты «Эркин Каракалпакстан».' WHERE id = 2200;
UPDATE fact_cards SET topic_ru = 'Мои звания и награды', question_ru = 'Какие звания и награды получил Ибрайим Юсупов?', fact_ru = 'В 1975 году мне было присвоено звание народного поэта Узбекистана и Каракалпакстана. В 1974 году я получил Государственную премию имени Бердаха, а в 2004 году удостоился звания Героя Узбекистана.' WHERE id = 2201;
UPDATE fact_cards SET topic_ru = 'Конец моей жизни', question_ru = 'Когда умер Ибрайим Юсупов?', fact_ru = 'Я скончался в 2008 году. Всю свою жизнь я верно служил поэзии.' WHERE id = 2202;
